                    wIm.color = new Color(0.61f, 0.76f, 0.91f, 1.0f);
                    wIm.raycastTarget = false;
                }
                wGo = new GameObject("__nvhSizeTitle", typeof(RectTransform), typeof(Text));
                wGo.transform.SetParent(GameObject.Find("__nvhPage2").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(170f, 24f);
                    wRt.anchoredPosition = new Vector2(-117.0f, -79.5f);
                }
                wTx = wGo.GetComponent<Text>();
                if (wTx != null) {
                    if (wFont != null) wTx.font = wFont;
                    wTx.fontSize = 12;
                    wTx.alignment = TextAnchor.UpperLeft;
                    wTx.horizontalOverflow = HorizontalWrapMode.Overflow;
                    wTx.verticalOverflow = VerticalWrapMode.Overflow;
                    wTx.supportRichText = false;
                    wTx.color = new Color(0.9f, 0.91f, 0.92f, 1.0f);
                    wTx.raycastTarget = false;
                    wTx.text = "Kich thuoc menu";
                }
                wGo = new GameObject("__nvhSizeTrk", typeof(RectTransform), typeof(Image));
                wGo.transform.SetParent(GameObject.Find("__nvhPage2").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(194f, 16f);
                    wRt.anchoredPosition = new Vector2(87.0f, -85.5f);
                }
                wIm = wGo.GetComponent<Image>();
                if (wIm != null) {
                    wIm.color = new Color(0.098f, 0.098f, 0.114f, 1.0f);
                    wIm.raycastTarget = true;
                }
                wGo = new GameObject("__nvhSizeFill", typeof(RectTransform), typeof(Image));
                wGo.transform.SetParent(GameObject.Find("__nvhPage2").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(97f, 16f);
                    wRt.anchoredPosition = new Vector2(38.5f, -85.5f);
                }
                wIm = wGo.GetComponent<Image>();
                if (wIm != null) {
                    wIm.color = new Color(0.2f, 0.66f, 0.95f, 1.0f);
                    wIm.raycastTarget = false;
                }
                wGo = new GameObject("__nvhPh3", typeof(RectTransform), typeof(Text));
                wGo.transform.SetParent(GameObject.Find("__nvhPage3").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(640f, 60f);
                    wRt.anchoredPosition = new Vector2(-110.0f, 52.5f);
                }
                wTx = wGo.GetComponent<Text>();
                if (wTx != null) {
                    if (wFont != null) wTx.font = wFont;
                    wTx.fontSize = 18;
                    wTx.alignment = TextAnchor.MiddleCenter;
                    wTx.horizontalOverflow = HorizontalWrapMode.Overflow;
                    wTx.verticalOverflow = VerticalWrapMode.Overflow;
                    wTx.supportRichText = false;
                    wTx.color = new Color(0.58f, 0.61f, 0.65f, 1.0f);
                    wTx.raycastTarget = false;
                    wTx.text = "Skin: doi bang lenh chat /skin <n>";
                }
                wGo = new GameObject("__nvhPh4", typeof(RectTransform), typeof(Text));
                wGo.transform.SetParent(GameObject.Find("__nvhPage4").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(640f, 60f);
                    wRt.anchoredPosition = new Vector2(-110.0f, 52.5f);
                }
                wTx = wGo.GetComponent<Text>();
                if (wTx != null) {
                    if (wFont != null) wTx.font = wFont;
                    wTx.fontSize = 18;
                    wTx.alignment = TextAnchor.MiddleCenter;
                    wTx.horizontalOverflow = HorizontalWrapMode.Overflow;
                    wTx.verticalOverflow = VerticalWrapMode.Overflow;
                    wTx.supportRichText = false;
                    wTx.color = new Color(0.58f, 0.61f, 0.65f, 1.0f);
                    wTx.raycastTarget = false;
                    wTx.text = "Ho tro tuong: chua bat (P4)";
                }
                wGo = new GameObject("__nvhPh5", typeof(RectTransform), typeof(Text));
                wGo.transform.SetParent(GameObject.Find("__nvhPage5").transform, false);
                wRt = wGo.GetComponent<RectTransform>();
                if (wRt != null) {
                    wRt.anchorMin = new Vector2(0.5f, 0.5f);
                    wRt.anchorMax = new Vector2(0.5f, 0.5f);
                    wRt.pivot = new Vector2(0.5f, 0.5f);
                    wRt.sizeDelta = new Vector2(640f, 60f);
                    wRt.anchoredPosition = new Vector2(-110.0f, 52.5f);
                }
                wTx = wGo.GetComponent<Text>();
                if (wTx != null) {
                    if (wFont != null) wTx.font = wFont;
                    wTx.fontSize = 18;
                    wTx.alignment = TextAnchor.MiddleCenter;
                    wTx.horizontalOverflow = HorizontalWrapMode.Overflow;
                    wTx.verticalOverflow = VerticalWrapMode.Overflow;
                    wTx.supportRichText = false;
                    wTx.color = new Color(0.58f, 0.61f, 0.65f, 1.0f);
                    wTx.raycastTarget = false;
                    wTx.text = "Chia se map: chua bat";
                }

                }

                // ---- áp vị trí kéo + tab đang chọn ----
                GameObject panelGo = GameObject.Find("__nvhPanel");
                if (panelGo != null)
                {
                    RectTransform prt2 = panelGo.GetComponent<RectTransform>();
                    if (prt2 != null) prt2.anchoredPosition = new Vector2(dragX, dragY);
                }
                int curTab = PlayerPrefs.GetInt("__nvhTab", 0);
                if (curTab < 0) curTab = 0;
                if (curTab > 5) curTab = 5;
                for (int i = 0; i < 6; i++)
                {
                    GameObject pg = GameObject.Find("__nvhPage" + i);
                    if (pg != null && pg.activeSelf != (i == curTab)) pg.SetActive(i == curTab);
                    GameObject tb = GameObject.Find("__nvhTab" + i);
                    if (tb != null)
                    {
                        Image ti = tb.GetComponent<Image>();
                        if (ti != null)
                            ti.color = (i == curTab)
                                ? new Color(0.145f, 0.158f, 0.17f, 1f)
                                : new Color(0.105f, 0.113f, 0.122f, 1f);
                    }
                }

                // ================= CHẠM =================
                if (tcount == 1)
                {
                    Touch t1 = Input.GetTouch(0);
                    if (t1.phase == TouchPhase.Began &&
                        PlayerPrefs.GetInt("__nvhTouchF", -1) != Time.frameCount)
                    {
                        PlayerPrefs.SetInt("__nvhTouchF", Time.frameCount);

                        float lx = t1.position.x - (Screen.width * 0.5f + dragX);
                        float ly = t1.position.y - (Screen.height * 0.5f + dragY);
                        bool handled = false;

                        // nút đóng
                        if (lx > 388f && lx < 448f && ly > 203f && ly < 258f)
                        {
                            handled = true;
                            PlayerPrefs.SetInt("__nvhMenuOpen", 0);
                            PlayerPrefs.Save();
                        }

                        // tab
                        for (int i = 0; i < 6 && !handled; i++)
                        {
                            float cx = 8f + 91f - 450f;
                            float cy = 262.5f - (82f + 58f * i) - 25f;
                            if (lx > cx - 91f && lx < cx + 91f &&
                                ly > cy - 25f && ly < cy + 25f)
                            {
                                handled = true;
                                PlayerPrefs.SetInt("__nvhTab", i);
                                PlayerPrefs.Save();
                            }
                        }

                        // 6 switch (tab ESP) — mỗi ô một PlayerPrefs key thật
                        if (!handled && curTab == 0)
                        {
                            for (int i = 0; i < 6 && !handled; i++)
                            {
                                int cell = (i == 1) ? 2 : (i == 2) ? 5 : (i == 3) ? 3
                                         : (i == 4) ? 4 : (i == 5) ? 1 : 0;
                                int col = cell % 2;
                                int row = cell / 2;
                                float cx = 105f + (214f + 340f * col + 164f - 345f);
                                float cy = -25f + (220f - (162f + 66f * row) - 27f);
                                if (lx > cx - 164f && lx < cx + 164f &&
                                    ly > cy - 27f && ly < cy + 27f)
                                {
                                    handled = true;
                                    string k = "iFix.ESP.Enabled.v1";
                                    if (i == 1) k = "iFix.ESP.Monster.v1";
                                    else if (i == 2) k = "iFix.HiddenHeroLines.v1";
                                    else if (i == 3) k = "iFix.Banner.v1";
                                    else if (i == 4) k = "iFix.AIM.TargetMode.v1";
                                    else if (i == 5) k = "iFix.Camera.Zoom.v1";
                                    int cur = PlayerPrefs.GetInt(k, 0);
                                    PlayerPrefs.SetInt(k, cur == 0 ? 1 : 0);
                                    PlayerPrefs.Save();
                                }
                            }
                        }

                        // 3 aim card (tab AIM):
                        //   card0 → iFix.AIM.Enabled.v1      (b22 pc482 đọc)
                        //   card1 → iFix.AIM.DrawMode.v1     (b22, 0=tắt 1=luôn 2=skill)
                        //   card2 → iFix.AIM.TargetMode.v1   (b22 pc482, 4 bậc)
                        if (!handled && curTab == 1)
                        {
                            for (int i = 0; i < 3 && !handled; i++)
                            {
                                float cx = 105f + (230f + 102.5f - 345f);
                                float cy = -25f + (220f - (304f + 67f * i) - 28f);
                                if (lx > cx - 102f && lx < cx + 102f &&
                                    ly > cy - 28f && ly < cy + 28f)
                                {
                                    handled = true;
                                    if (i == 0)
                                    {
                                        int v = PlayerPrefs.GetInt("iFix.AIM.Enabled.v1", 0);
                                        PlayerPrefs.SetInt("iFix.AIM.Enabled.v1", v == 0 ? 1 : 0);
                                    }
                                    else if (i == 1)
                                    {
                                        int v = PlayerPrefs.GetInt("iFix.AIM.DrawMode.v1", 0);
                                        PlayerPrefs.SetInt("iFix.AIM.DrawMode.v1", (v + 1) % 3);
                                    }
                                    else
                                    {
                                        int v = PlayerPrefs.GetInt("iFix.AIM.TargetMode.v1", 0);
                                        PlayerPrefs.SetInt("iFix.AIM.TargetMode.v1", (v + 1) % 4);
                                    }
                                    PlayerPrefs.Save();
                                }
                            }
                        }

                        // tab Memory: 3 hàng auto (key thật) + slider size
                        if (!handled && curTab == 2)
                        {
                            for (int i = 0; i < 3 && !handled; i++)
                            {
                                float cx = 105f + (230f + 160f - 345f);
                                float cy = -25f + (220f - (150f + 60f * i) - 24f);
                                if (lx > cx - 160f && lx < cx + 160f &&
                                    ly > cy - 24f && ly < cy + 24f)
                                {
                                    handled = true;
                                    string k = "iFix.AutoSmite.Enabled.v1";
                                    if (i == 1) k = "iFix.AutoBP.Enabled.v1";
                                    else if (i == 2) k = "iFix.AutoIce.Enabled.v1";
                                    int v = PlayerPrefs.GetInt(k, 0);
                                    PlayerPrefs.SetInt(k, v == 0 ? 1 : 0);
                                    PlayerPrefs.Save();
                                }
                            }
                            if (!handled)
                            {
                                float cx = 105f + (440f + 97f - 345f);
                                float cy = -25f + (220f - 340f - 8f);
                                if (lx > cx - 97f && lx < cx + 97f &&
                                    ly > cy - 12f && ly < cy + 12f)
                                {
                                    handled = true;
                                    float u = (lx - (cx - 97f)) / 194f;
                                    if (u < 0f) u = 0f;
                                    if (u > 1f) u = 1f;
                                    PlayerPrefs.SetFloat("__nvhScale", 0.75f + u * 0.5f);
                                    PlayerPrefs.Save();
                                }
                            }
                        }

                        // kéo panel: bấm trong header, không trúng widget
                        if (!handled && ly > 197.5f && ly < 262.5f && lx > -450f && lx < 295f)
                        {
                            PlayerPrefs.SetInt("__nvhDrag", 1);
                            PlayerPrefs.SetFloat("__nvhDragX", lx);
                            PlayerPrefs.SetFloat("__nvhDragY", ly);
                            PlayerPrefs.Save();
                        }
                    }
                    else if (t1.phase == TouchPhase.Moved &&
                             PlayerPrefs.GetInt("__nvhDrag", 0) == 1)
                    {
                        float nx = dragX + (t1.position.x - (Screen.width * 0.5f + dragX)
                                            - PlayerPrefs.GetFloat("__nvhDragX", 0f));
                        float ny = dragY + (t1.position.y - (Screen.height * 0.5f + dragY)
                                            - PlayerPrefs.GetFloat("__nvhDragY", 0f));
                        float s = PlayerPrefs.GetFloat("__nvhScale", 1f);
                        float cxL = Screen.width * 0.5f - 450f * s - 8f;
                        float cyL = Screen.height * 0.5f - 262.5f * s - 8f;
                        if (cxL < 0f) cxL = 0f;
                        if (cyL < 0f) cyL = 0f;
                        if (nx < -cxL) nx = -cxL;
                        if (nx > cxL) nx = cxL;
                        if (ny < -cyL) ny = -cyL;
                        if (ny > cyL) ny = cyL;
                        PlayerPrefs.SetFloat("__nvhPanelX", nx);
                        PlayerPrefs.SetFloat("__nvhPanelY", ny);
                    }
                    else if (t1.phase == TouchPhase.Ended || t1.phase == TouchPhase.Canceled)
                    {
                        if (PlayerPrefs.GetInt("__nvhDrag", 0) != 0)
                        {
                            PlayerPrefs.SetInt("__nvhDrag", 0);
                            PlayerPrefs.Save();
                        }
                    }
                }

                // ================= VẼ LẠI (5 Hz) =================
                if (doSlow)
                {
                    for (int i = 0; i < 6; i++)
                    {
                        string k = "iFix.ESP.Enabled.v1";
                        if (i == 1) k = "iFix.ESP.Monster.v1";
                        else if (i == 2) k = "iFix.HiddenHeroLines.v1";
                        else if (i == 3) k = "iFix.Banner.v1";
                        else if (i == 4) k = "iFix.AIM.TargetMode.v1";
                        else if (i == 5) k = "iFix.Camera.Zoom.v1";
                        bool on = PlayerPrefs.GetInt(k, 0) != 0;
                        GameObject tr = GameObject.Find("__nvhSwTrack" + i);
                        if (tr != null)
                        {
                            Image ti = tr.GetComponent<Image>();
                            if (ti != null)
                                ti.color = on ? new Color(0f, 0.45f, 0.8f, 1f)
                                              : new Color(0.61f, 0.76f, 0.91f, 1f);
                        }
                        GameObject kn = GameObject.Find("__nvhSwKnob" + i);
                        if (kn != null)
                        {
                            RectTransform kr = kn.GetComponent<RectTransform>();
                            if (kr != null)
                                kr.anchoredPosition = new Vector2(on ? 119f : 97f, 0f);
                        }
                    }

                    // 3 hàng Memory
                    for (int i = 0; i < 3; i++)
                    {
                        string k = "iFix.AutoSmite.Enabled.v1";
                        if (i == 1) k = "iFix.AutoBP.Enabled.v1";
                        else if (i == 2) k = "iFix.AutoIce.Enabled.v1";
                        bool on = PlayerPrefs.GetInt(k, 0) != 0;
                        GameObject tr2 = GameObject.Find("__nvhMemTrack" + i);
                        if (tr2 != null)
                        {
                            Image ti2 = tr2.GetComponent<Image>();
                            if (ti2 != null)
                                ti2.color = on ? new Color(0f, 0.45f, 0.8f, 1f)
                                               : new Color(0.61f, 0.76f, 0.91f, 1f);
                        }
                    }

                    // 3 aim card: màu theo trạng thái
                    {
                        bool a0 = PlayerPrefs.GetInt("iFix.AIM.Enabled.v1", 0) != 0;
                        GameObject c0 = GameObject.Find("__nvhAim0");
                        if (c0 != null)
                        {
                            Image ci = c0.GetComponent<Image>();
                            if (ci != null)
                                ci.color = a0 ? new Color(0.20f, 0.66f, 0.95f, 1f)
                                              : new Color(0.145f, 0.158f, 0.17f, 1f);
                        }
                        bool a2 = PlayerPrefs.GetInt("iFix.AIM.TargetMode.v1", 0) != 0;
                        GameObject c2 = GameObject.Find("__nvhAim2");
                        if (c2 != null)
                        {
                            Image ci = c2.GetComponent<Image>();
                            if (ci != null)
                                ci.color = a2 ? new Color(0.20f, 0.66f, 0.95f, 1f)
                                              : new Color(0.145f, 0.158f, 0.17f, 1f);
                        }
                    }

                    float sc = PlayerPrefs.GetFloat("__nvhScale", 1f);
                    if (sc < 0.75f) sc = 0.75f;
                    if (sc > 1.25f) sc = 1.25f;
                    if (panelGo != null)
                        panelGo.transform.localScale = new Vector3(sc, sc, 1f);

                    // cam zoom → fill thanh (dùng key sẵn có của Bola)
                    float z = PlayerPrefs.GetFloat("iFix.Camera.Zoom.v1", 1f);
                    float zu = (z - 1f) / 1.3f;
                    if (zu < 0f) zu = 0f;
                    if (zu > 1f) zu = 1f;
                    GameObject zf = GameObject.Find("__nvhSizeFill");
                    if (zf != null)
                    {
                        RectTransform zr = zf.GetComponent<RectTransform>();
                        if (zr != null) zr.sizeDelta = new Vector2(97f + zu * 97f, 16f);
                    }

                    // nhịp tim: ghi file, KHÔNG dùng ToString() trên số (IFix resolve sai)
                    try
                    {
                        string hb = System.Environment.GetEnvironmentVariable("HOME");
                        if (hb != null && hb.Length > 0)
                        {
                            int beat = (__mCalls / 20) % 2;
                            System.IO.File.WriteAllText(hb + "/Documents/nvh_menu_hb.txt",
                                                        (beat == 0) ? "B0" : "B1");
                        }
                    }
                    catch (Exception) { }
                }
            }
            catch (Exception)
            {
                try
                {
                    string h = System.Environment.GetEnvironmentVariable("HOME");
                    if (h != null && h.Length > 0)
                        System.IO.File.WriteAllText(h + "/Documents/nvh_menu_err.txt", "E");
                }
                catch (Exception) { }
            }
        }
    }
}
